result.text:
  white-space: pre-wrap;
  word-break: break-word;
}
.raw-text mark { background: #fff3bf; color: #6b4a00; padding: 0 1px; border-radius: 2px; }

.summary-box {
  background: var(--brand-soft);
  border: 1px solid var(--brand-soft-2);
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  font-size: 13px;
  color: var(--brand-2);
  display: flex;
  gap: 9px;
}
.summary-box svg { width: 17px; height: 17px; flex: 0 0 auto; margin-top: 1px; }
.summary-box.warn { background: var(--warn-soft); border-color: #f0dcb8; color: #6f3c05; }

.checkline { display: flex; align-items: center; gap: 7px; font-size: 13px; color: var(--ink-2); }
.checkline input { width: 15px; height: 15px; accent-color: var(--brand); }

/* ---------- Avisos ------------------------------------------------------ */

.toasts {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 90;
  display: flex;
  flex-direction: column;
  gap: 9px;
  max-width: min(380px, calc(100vw - 40px));
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  background: #18231f;
  color: #fff;
  padding: 11px 14px;
  border-radius: 11px;
  font-size: 13.5px;
  box-shadow: var(--shadow-md);
  animation: rise .2s ease both;
}
.toast svg { width: 16px; height: 16px; flex: 0 0 auto; margin-top: 2px; }
.toast.ok svg { color: #6fd39c; }
.toast.bad svg { color: #ff9d92; }
.toast.out { animation: fadeout .25s ease forwards; }

/* ---------- Gráfico de barras ------------------------------------------- */

.bars {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  height: 132px;
  padding-top: 8px;
}
.bars .bar-col { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; gap: 6px; height: 100%; min-width: 0; }
.bars .bar-stack { display: flex; flex-direction: column; justify-content: flex-end; height: 100%; gap: 2px; }
.bars .bar {
  border-radius: 5px 5px 2px 2px;
  min-height: 3px;
  background: var(--brand-soft-2);
  transition: height .4s ease;
}
.bars .bar.paid { background: linear-gradient(180deg, #2f9d6c, #157347); border-radius: 5px; }
.bars .bar.pending { background: linear-gradient(180deg, #e0a95c, #c2761a); border-radius: 2px; }
